def replace_command(command, broken, matched):
    """Helper for *_no_command rules."""
    new_cmds = get_close_matches(broken, matched, cutoff=0.1)
    return [replace_argument(command.script, broken, new_cmd.strip())
            for new_cmd in new_cmds]

def __find_rows(self, find_url, **attributes):
        """
            :param find_url: URL of the find api
            :type find_url: string
            :return: The Response returned by requests including the list of documents based on find_url
            :rtype: Response object
        """
        req = self.url + find_url

        # Add range and sort parameters
        params = {
            "range": attributes.get("range", "all"),
            "sort": attributes.get("sort", [])
        }

        # Add body
        data = {
            "query": attributes.get("query", {})
        }

        try:
            return requests.post(req, params=params, json=data, proxies=self.proxies, auth=self.auth, verify=self.cert)
        except requests.exceptions.RequestException as e:
            raise TheHiveException("Error: {}".format(e))

def generate_checker(value):
    """Generate state checker for given value."""
    if isinstance(value, str):
        return f"{value} == state"
    elif isinstance(value, list):
        return f"state in {value}"
    else:
        raise ValueError(f"Invalid value: {value}")

def generate_checker(value):
    """Generate state checker for given value."""
    @property
    @wraps(can_be_)
    def checker(self):
        return self.can_be_(value)

    return checker

def service_name_from_scope_name(scope_name):
    """Translate scope name to service name which can be used in dns.

    230 = 253 - len('replica.') - len('.service.consul')
    """

    def replace_char(match):
        c = match.group(0)
        return '-' if c in '. _' else "u{:04d}".format(ord(c))

    service_name = re.sub(r'[^a-z0-9\-]', replace_char, scope_name.lower())
    return service_name[0:230]

def data_find_all(data, path, dyn_cls=False):
    """Find and return all element-as-tuples in tuple ``data`` using simplified
    XPath ``path``.
    """
    if dyn_cls:
        return data_find_all_dyn_cls(data, path)
    else:
        return data_find_all_cls(data, path)

def data_find_all(data, path, dyn_cls=False):
    """Find and return all element-as-tuples in tuple ``data`` using simplified
    XPath ``path``.
    """
    path_parts = path.split("/")
    try:
        sub_elms = tuple(
            el
            for el in data
            if isinstance(el, (tuple, list)) and el[0] == path_parts[0]
        )
    except IndexError:
        return None
    if len(path_parts) > 1:
        ret = []
        for sub_elm in sub_elms:
            for x in data_find_all(sub_elm, "/".join(path_parts[1:])):
                ret.append(x)
        ret = tuple(ret)
    else:
        ret = sub_elms
    if ret and dyn_cls:
        cls = generate_element_class(ret[0])
        return tuple(cls(data=tuple_) for tuple_ in ret)
    return ret

def create_contentkey_authorization_policy(access_token, content):
    """Create Media Service Content Key Authorization Policy.

    Args:
        access_token (str): A valid Azure authentication token.
        content (str): Content Payload.

    Returns:
        HTTP response. JSON body.
    """
    url = 'https://media.windows.net/api/ContentKeyAuthorizationPolicies'
    headers = {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + access_token,
        'x-ms-version': '2.11'
    }
    body = {
        'Name': 'ContentKeyAuthorizationPolicy_' + str(uuid.uuid4()),
        'KeyDeliveryType': 'PlayReadyLicense',
        'Rights': ['Play'],
        'ContentKeyAuthorizationPolicyOptions': [{
            'Configuration': content,
            'Restriction': {
                'Name': 'TokenRestrictionTemplate',
                'TokenType': 'JWT',
                'Audience': 'urn:microsoft:azure:mediaservices:contentkey',
                'Issuer': 'urn:microsoft:azure:mediaservices'
            }
        }]
    }
    response = requests.post(url, headers=headers, json=body)
    return response

def enqueue(self, future):
    """
    Enqueue a future to be processed by one of the threads in the pool.
    The future must be bound to a worker and not have been started yet.
    """
    if future._state != _state.PENDING:
        raise ValueError('future is not pending')
    if future._worker is not None:
        raise ValueError('future is already bound to a worker')
    if future._state == _state.CANCELLED:
        raise ValueError('future is already cancelled')
    if future._state == _state.FINISHED:
        raise ValueError('future is already finished')
    if future._state == _state.CANCELLED:
        raise ValueError('future is already cancelled')

    # Add the future to the queue.
    self._queue.put(future)

    # If we're not already running, start one of the threads.
    if self._processes is None:
        self._processes = []
        for i in range(self._processes_count):
            process = self._ctx.Process(target=self._worker,
                                        args=(self._queue, self._done))
            process.daemon = True
            process.start()
            self._processes.append(process)

def stash(self, stash_name: str):
        """
        Stashes the current working tree changes

        :param stash_name: name of the stash
        :type stash_name: str
        """
        if self.stashed:
            LOGGER.error('already stashed')
            sys.exit(-1)
        else:
            if not self.index_is_empty():
                LOGGER.error('cannot stash; index is not empty')
                sys.exit(-1)
            if self.untracked_files():
                LOGGER.error('cannot stash; there are untracked files')
                sys.exit(-1)
            if self.changed_files():
                LOGGER.info('stashing changes')
                self.repo.git.stash('push', '-u', '-k', '-m', f'"{stash_name}"')
                self.stashed = True
            else:
                LOGGER.info('no changes to stash')

