        while not self._at_eof:
            await self.read_chunk(self.chunk_size)

def _not_in(x, y):
    """Compute the vectorized membership of ``x not in y`` if possible,
    otherwise use Python.
    """
    if hasattr(x, "__array_ufunc__"):
        return ~x.__array_ufunc__(operator.contains, y)
    else:
        return [i not in y for i in x]

def _not_in(x, y):
    """Compute the vectorized membership of ``x not in y`` if possible,
    otherwise use Python.
    """
    try:
        return ~x.isin(y)
    except AttributeError:
        if is_list_like(x):
            try:
                return ~y.isin(x)
            except AttributeError:
                pass
        return x not in y

def get_cases(self, skip_ws=False):
        """Returns a list of 2-tuples (condition, value).

        If an ELSE exists condition is None.
        """
        cases = []
        while True:
            if skip_ws:
                self.skip_ws()
            if self.current_char == '}':
                break
            if self.current_char == '|':
                self.next_char()
                if self.current_char == '|':
                    self.next_char()
                    if self.current_char == '}':
                        break
                    else:
                        raise SyntaxError('Expected "}"')
                else:
                    raise SyntaxError('Expected "|"')
            condition = self.get_condition()
            if self.current_char == '|':
                self.next_char()
                if self.current_char == '|':
                    self.next_char()
                    if self.current_char == '}':
                        break
                    else:
                        raise SyntaxError('Expected "}"')
                else:
                    raise SyntaxError('Expected "|"')
            if self.current_char == '=':
                self.next_char()
                value = self.get_value()
                cases.append((condition, value))
            else:
                raise SyntaxError('Expected "="')
        return cases

def get_cases(self, skip_ws=False):
        """Returns a list of 2-tuples (condition, value).

        If an ELSE exists condition is None.
        """
        CONDITION = 1
        VALUE = 2

        ret = []
        mode = CONDITION

        for token in self.tokens:
            # Set mode from the current statement
            if token.match(T.Keyword, 'CASE'):
                continue

            elif skip_ws and token.ttype in T.Whitespace:
                continue

            elif token.match(T.Keyword, 'WHEN'):
                ret.append(([], []))
                mode = CONDITION

            elif token.match(T.Keyword, 'THEN'):
                mode = VALUE

            elif token.match(T.Keyword, 'ELSE'):
                ret.append((None, []))
                mode = VALUE

            elif token.match(T.Keyword, 'END'):
                mode = None

            # First condition without preceding WHEN
            if mode and not ret:
                ret.append(([], []))

            # Append token depending of the current mode
            if mode == CONDITION:
                ret[-1][0].append(token)

            elif mode == VALUE:
                ret[-1][1].append(token)

        # Return cases list
        return ret

def forget(self):
        """
        Reset _observed events. Remove self from observers.
        :return: Nothing
        """
        for key in self._observed:
            self._observed[key].remove(self)
        self._observed = {}

def forget(self):
        """
        Reset _observed events. Remove self from observers.
        :return: Nothing
        """
        self._observed_events = {}
        if self in self._observers:
            self._observers.remove(self)

def _execute_callback(self, callback, data):
        """Execute the callback in another thread. Wait for and return the results."""
        if callback is None:
            return None

        if not isinstance(callback, Callback):
            raise TypeError("callback must be a Callback")

        if not isinstance(data, dict):
            raise TypeError("data must be a dict")

        if self.thread_pool is None:
            self.thread_pool = ThreadPool(self.thread_pool_size)

        future = self.thread_pool.submit(callback.execute, data)
        return future.result()

def _execute_callback(self, callback, data):
        """Execute the callback in another thread. Wait for and return the results."""
        web_client = WebClient(
            token=self.token, base_url=self.base_url, ssl=self.ssl, proxy=self.proxy
        )
        with concurrent.futures.ThreadPoolExecutor(max_workers=1) as executor:
            # Execute the callback on a separate thread,
            future = executor.submit(
                callback, rtm_client=self, web_client=web_client, data=data
            )

            while future.running():
                pass

            future.result()

