        """
        Load a set of conversations by their keys.
        """
        return cls.objects.filter(key__in=keys)

def load(cls, keys):
        """
        Load a set of conversations by their keys.
        """
        conversations = []
        for key in keys:
            conversation = unitdata.kv().get(key)
            if conversation:
                conversations.append(cls.deserialize(conversation))
        return conversations

def _get_debug_formatter(conf):
    """Get debug formatter based on configuration.

    :param conf: configurtration namespace (ex. argparser)

    --debug: log line numbers, file data
    --verbose: standard log format at a DEBUG loglevel
    --quiet: turn down logging output (logging.WARNING)
    default is logging.INFO
    """
    if conf.debug:
        return _get_debug_formatter_with_lineno()
    elif conf.verbose:
        return _get_verbose_formatter()
    elif conf.quiet:
        return _get_quiet_formatter()
    else:
        return _get_default_formatter()

def _get_debug_formatter(conf):
    """Get debug formatter based on configuration.

    :param conf: configurtration namespace (ex. argparser)

    --debug: log line numbers, file data
    --verbose: standard log format at a DEBUG loglevel
    --quiet: turn down logging output (logging.WARNING)
    default is logging.INFO
    """
    if conf.debug is True:
        return DebugFormatter('%(pathname)s:%(lineno)d: %(levelname)-8s '
                              '%(message)s')
    elif conf.verbose is True:
        return logging.Formatter(
            '%(name)-30s: %(levelname)-8s %(message)s')
    elif conf.quiet is True:
        return logging.Formatter('%(message)s')
    else:
        return logging.Formatter(logging.BASIC_FORMAT)

def poi_coords(poi_id, *, raw=False):
    """
    DVB Map Coordinates
    (GET https://www.dvb.de/apps/map/coordinates)

    :param poi_id: Id of poi
    :param raw: Return raw response
    :return: Coordinates of poi
    """
    try:
        r = requests.get(
            url='https://www.dvb.de/apps/map/coordinates',
            params={
                'id': poi_id,
            },
        )
        if r.status_code == 200:
            response = json.loads(r.content.decode('utf-8'))
        else:
            raise requests.HTTPError('HTTP Status: {}'.format(r.status_code))
    except requests.RequestException as e:
        print('Failed to access DVB map coordinates app. Request Exception', e)
        response = None

    if response is None or raw:
        return response

    coords = [int(i) for i in response.split('|')]
    lat, lng = gk4_to_wgs(coords[0], coords[1])
    return {
        'lat': lat,
        'lng': lng
    }

def _reflect_all(exclude_tables=None, admin=None, read_only=False, schema=None):
    """Register all tables in the given database as services.

    :param list exclude_tables: A list of tables to exclude from the API
                                service
    """
    from . import api
    from . import models
    from . import admin

    if exclude_tables is None:
        exclude_tables = []

    if schema is None:
        schema = api.schema

    for table in models.db.metadata.sorted_tables:
        if table.name in exclude_tables:
            continue

        if read_only:
            api.read_only(table)
        else:
            api.service(table)

    if admin is not None:
        admin.init_app(app)

    return api

def _reflect_all(exclude_tables=None, admin=None, read_only=False, schema=None):
    """Register all tables in the given database as services.

    :param list exclude_tables: A list of tables to exclude from the API
                                service
    """
    AutomapModel.prepare(  # pylint:disable=maybe-no-member
        db.engine, reflect=True, schema=schema)
    for cls in AutomapModel.classes:
        if exclude_tables and cls.__table__.name in exclude_tables:
            continue
        if read_only:
            cls.__methods__ = {'GET'}
        register_model(cls, admin)

