def process_signal(self, signum):
        """Invoked whenever a signal is added to the stack.

        :param int signum: The signal that was added

        """
        if signum == signal.SIGINT:
            self.logger.info("SIGINT received, shutting down")
            self.shutdown()
        elif signum == signal.SIGTERM:
            self.logger.info("SIGTERM received, shutting down")
            self.shutdown()
        elif signum == signal.SIGHUP:
            self.logger.info("SIGHUP received, reloading configuration")
            self.reload()
        elif signum == signal.SIGUSR1:
            self.logger.info("SIGUSR1 received, dumping stack traces")
            self.dump_stack_traces()
        elif signum == signal.SIGUSR2:
            self.logger.info("SIGUSR2 received, dumping process info")
            self.dump_process_info()
        else:
            self.logger.info("Signal %s received, ignoring", signum)

def process_signal(self, signum):
        """Invoked whenever a signal is added to the stack.

        :param int signum: The signal that was added

        """
        if signum == signal.SIGTERM:
            LOGGER.info('Received SIGTERM, initiating shutdown')
            self.stop()
        elif signum == signal.SIGHUP:
            LOGGER.info('Received SIGHUP')
            if self.config.reload():
                LOGGER.info('Configuration reloaded')
                logging.config.dictConfig(self.config.logging)
                self.on_configuration_reloaded()
        elif signum == signal.SIGUSR1:
            self.on_sigusr1()
        elif signum == signal.SIGUSR2:
            self.on_sigusr2()

def expand_region(tuple_of_s, a, b, start=0, stop=None):
    """Apply expend_slice on a tuple of slices"""
    if stop is None:
        stop = len(a)
    return tuple(expand_slice(s, a, b, start, stop) for s in tuple_of_s)

def expand_region(tuple_of_s, a, b, start=0, stop=None):
    """Apply expend_slice on a tuple of slices"""
    return tuple(expand_slice(s, a, b, start=start, stop=stop)
                 for s in tuple_of_s)

def _restore_file(path, delete_backup=True):
    """
    Restore a file if it exists and remove the backup
    """
    if os.path.exists(path):
        if delete_backup:
            os.remove(path + '.bak')
        else:
            os.rename(path + '.bak', path)

def _restore_file(path, delete_backup=True):
    """
    Restore a file if it exists and remove the backup
    """
    backup_base = '/var/local/woven-backup'
    backup_path = ''.join([backup_base,path])
    if exists(backup_path):
        if delete_backup:
            sudo('mv -f %s %s'% (backup_path,path))
        else:
            sudo('cp -f %s %s'% (backup_path,path))

def _get_value_from_json(self, dict_path, metrics_json):
        """
        Get a value from a dictionary under N keys, represented as str("key1.key2...key{n}")
        """
        for key in dict_path.split('.'):
            if key in metrics_json:
                metrics_json = metrics_json.get(key)
            else:
                return None
        return metrics_json

