def restore(self, fade=False):
        """Restore the state of a device to that which was previously saved.

        For coordinator devices restore everything. For slave devices
        only restore volume etc., not transport info (transport info
        comes from the slave's coordinator).

        Args:
            fade (bool): Whether volume should be faded up on restore.
        """

        try:
            if self.is_coordinator:
                self._restore_coordinator()
        finally:
            self._restore_volume(fade)

        # Now everything is set, see if we need to be playing, stopped
        # or paused ( only for coordinators)
        if self.is_coordinator:
            if self.transport_state == 'PLAYING':
                self.device.play()
            elif self.transport_state == 'STOPPED':
                self.device.stop()

def _md5_compare(self, file_path, checksum, block_size=2 ** 13):
        """Compare a given MD5 checksum with one calculated from a file."""
        if not checksum:
            return False
        if not os.path.exists(file_path):
            return False
        with open(file_path, 'rb') as f:
            md5 = hashlib.md5()
            while True:
                data = f.read(block_size)
                if not data:
                    break
                md5.update(data)
            return md5.hexdigest() == checksum

def _md5_compare(self, file_path, checksum, block_size=2 ** 13):
        """Compare a given MD5 checksum with one calculated from a file."""
        with closing(self._tqdm(desc="MD5 checksumming", total=getsize(file_path), unit="B",
                                unit_scale=True)) as progress:
            md5 = hashlib.md5()
            with open(file_path, "rb") as f:
                while True:
                    block_data = f.read(block_size)
                    if not block_data:
                        break
                    md5.update(block_data)
                    progress.update(len(block_data))
            return md5.hexdigest().lower() == checksum.lower()

def _reorder(string, salt):
    """Reorders `string` according to `salt`."""
    return ''.join(sorted(string, key=salt.get))

def moving_average(data, periods, type='simple'):
    """
    compute a <periods> period moving average.
    type is 'simple' | 'exponential'
    """
    if type == 'simple':
        return data.rolling(periods).mean()
    elif type == 'exponential':
        return data.ewm(span=periods).mean()
    else:
        raise ValueError("type must be 'simple' or 'exponential'")

def to_data(self, value):
        """
        Coerce python data type to simple form for serialization.
        If default value was defined returns the default value if None was passed.
        Throw exception is value is ``None`` is ``required`` is set to ``True``
        """
        if value is None:
            if self.required:
                raise ValueError("Required field %s is None" % self.name)
            else:
                return self.default
        elif isinstance(value, str):
            return value
        elif isinstance(value, int):
            return str(value)
        elif isinstance(value, float):
            return str(value)
        elif isinstance(value, bool):
            return str(value).lower()
        elif isinstance(value, list):
            return [self.to_data(v) for v in value]
        elif isinstance(value, dict):
            return {k: self.to_data(v) for k, v in value.items()}
        else:
            raise ValueError("Unsupported type %s for field %s" % (type(value), self.name))

def to_data(self, value):
        """
        Coerce python data type to simple form for serialization.
        If default value was defined returns the default value if None was passed.
        Throw exception is value is ``None`` is ``required`` is set to ``True``
        """
        try:
            if value is None and self._default is not None:
                return self._export(self.default)
            self._check_required(value)
            value = self._export(value)
            return value
        except ValueError as ex:
            raise ValueError(ex, self._errors['to_data'])

def _matmul_with_relative_keys_2d(x, y, heads_share_relative_embedding):
  """Helper function for dot_product_unmasked_self_attention_relative_2d."""
  if heads_share_relative_embedding:
    ret = tf.einsum("bhxyd,md->bhxym", x, y)
  else:
    ret = tf.einsum("bhxyd,hmd->bhxym", x, y)
  return ret

