def clean_text(self, domain, **kwargs):
        """Try to extract only the domain bit from the """
        if domain is None:
            return None
        if domain.startswith('http://'):
            domain = domain[7:]
        if domain.startswith('https://'):
            domain = domain[8:]
        if domain.startswith('www.'):
            domain = domain[4:]
        return domain

def generate_config_parser(config, include_all=False):
    """
    Generates a config parser from a configuration dictionary.

    The dictionary contains the merged informations of the schema and,
    optionally, of a source configuration file. Values of the source
    configuration file will be stored in the *value* field of an option.
    """
    parser = ConfigParser.SafeConfigParser()
    for section in config:
        if section not in parser.sections():
            parser.add_section(section)
        for option in config[section]:
            if option not in parser.options(section):
                parser.set(section, option, config[section][option]['value'])
            else:
                if include_all:
                    parser.set(section, option, config[section][option]['value'])
    return parser

def is_valid_preview(preview):
