def Compile(self, filter_implementation):
    """Compile the binary expression into a filter object."""
    if filter_implementation == 'python':
      return self._CompilePython(filter_implementation)
    elif filter_implementation == 'native':
      return self._CompileNative(filter_implementation)
    else:
      raise ValueError('Unknown filter implementation: %s' %
                       filter_implementation)

def Compile(self, filter_implementation):
    """Compile the binary expression into a filter object."""
    operator = self.operator.lower()
    if operator in ('and', '&&'):
      method = 'AndFilter'
    elif operator in ('or', '||'):
      method = 'OrFilter'
    else:
      raise errors.ParseError(
          'Invalid binary operator {0:s}.'.format(operator))

    args = [x.Compile(filter_implementation) for x in self.args]
    return filter_implementation.FILTERS[method](arguments=args)

def get_absolute_name(self):
        """ Returns the full dotted name of this field """
        return self.model._meta.app_label + '.' + self.name

def get_absolute_name(self):
        """ Returns the full dotted name of this field """
        res = []
        current = self

        while type(current) != type(None):
            if current.__matched_index:
                res.append('$')
            res.append(current.get_type().db_field)
            current = current._get_parent()
        return '.'.join(reversed(res))

def get_translation(self, lang, field):
        """
        Return the translation string of an specific field in a Translatable
        istance

        @type lang: string
        @param lang: a string with the name of the language

        @type field: string
        @param field: a string with the name that we try to get

        @rtype: string
        @return: Returns a translation string
        """
        if field in self.translations:
            if lang in self.translations[field]:
                return self.translations[field][lang]
            else:
                return self.translations[field]['en']
        else:
            return ''

def get_translation(self, lang, field):
        """
        Return the translation string of an specific field in a Translatable
        istance

        @type lang: string
        @param lang: a string with the name of the language

        @type field: string
        @param field: a string with the name that we try to get

        @rtype: string
        @return: Returns a translation string
        """
        # Read from cache
        key = self._get_translation_cache_key(lang, field)
        trans = cache.get(key, '')

        if not trans:
            trans_obj = self.get_translation_obj(lang, field)
            trans = getattr(trans_obj, 'translation', '')
            # if there's no translation text fall back to the model field
            if not trans:
                trans = getattr(self, field, '')
            # update cache
            cache.set(key, trans)
        return trans

def convert_machine_list_value(name: str, value: str) -> \
        Union[datetime.datetime, str, int]:
    """Convert sizes and time values.

    Size will be ``int`` while time value will be :class:`datetime.datetime`.
    """
    if name in ('size', 'time'):
        return int(value)
    elif name == 'time':
        return datetime.datetime.strptime(value, '%Y-%m-%d %H:%M:%S')
    return value

def convert_machine_list_value(name: str, value: str) -> \
        Union[datetime.datetime, str, int]:
    """Convert sizes and time values.

    Size will be ``int`` while time value will be :class:`datetime.datetime`.
    """
    if name == 'modify':
        return convert_machine_list_time_val(value)
    elif name == 'size':
        return int(value)
    else:
        return value

def GET_namespace_num_names(self, path_info, namespace_id):
        """
        Get the number of names in a namespace
        Reply the number on success
        Reply 404 if the namespace does not exist
        Reply 502 on failure to talk to the blockstack server
        """
        try:
            namespace_info = self.get_namespace_info(namespace_id)
            if namespace_info is None:
                return self.reply_404()
            return self.reply_200(namespace_info['num_names'])
        except Exception as e:
            return self.reply_502(str(e))

def GET_namespace_num_names(self, path_info, namespace_id):
        """
        Get the number of names in a namespace
        Reply the number on success
        Reply 404 if the namespace does not exist
        Reply 502 on failure to talk to the blockstack server
        """
        if not check_namespace(namespace_id):
            return self._reply_json({'error': 'Invalid namespace'}, status_code=400)

        blockstackd_url = get_blockstackd_url()
        name_count = blockstackd_client.get_num_names_in_namespace(namespace_id, hostport=blockstackd_url)
        if json_is_error(name_count):
            log.error("Failed to load namespace count for {}: {}".format(namespace_id, name_count['error']))
            return self._reply_json({'error': 'Failed to load namespace count: {}'.format(name_count['error'])}, status_code=404)

        self._reply_json({'names_count': name_count})

