def mouseReleaseEvent(self, event):
        """
        Reimplements the :meth:`QLabel.mouseReleaseEvent` method.

        :param event: QEvent.
        :type event: QEvent
        """

        if self.underMouse():
            if self.__checkable:
                self.set_checked(not self.__checked)
            else:
                self.setPixmap(self.__active_pixmap)
        else:
            self.setPixmap(self.__default_pixmap)
        self.released.emit()
        self.clicked.emit()

def warmup(f):
    """ Decorator to run warmup before running a command """

    @wraps(f)
    def wrapped(self, *args, **kwargs):
        if not self.warmed_up:
            self.warmup()
        return f(self, *args, **kwargs)
    return wrapped

def parse_schema_definition(lexer: Lexer) -> SchemaDefinitionNode:
    """SchemaDefinition"""
    start = lexer.token
    expect_keyword(lexer, "schema")
    directives = parse_directives(lexer, True)
    operation_types = many_nodes(
        lexer, TokenKind.BRACE_L, parse_operation_type_definition, TokenKind.BRACE_R
    )
    return SchemaDefinitionNode(
        directives=directives, operation_types=operation_types, loc=loc(lexer, start)
    )

def is_method(arg, min_arity=None, max_arity=None):
    """Check if argument is a method.

    Optionally, we can also check if minimum or maximum arities
    (number of accepted arguments) match given minimum and/or maximum.
    """
    if not isinstance(arg, MethodType):
        return False

    if min_arity is not None and arg.arity < min_arity:
        return False

    if max_arity is not None and arg.arity > max_arity:
        return False

    return True

def is_method(arg, min_arity=None, max_arity=None):
    """Check if argument is a method.

    Optionally, we can also check if minimum or maximum arities
    (number of accepted arguments) match given minimum and/or maximum.
    """
    if not callable(arg):
        return False

    if not any(is_(arg) for is_ in (inspect.ismethod,
                                    inspect.ismethoddescriptor,
                                    inspect.isbuiltin)):
        return False

    try:
        argnames, varargs, kwargs, defaults = getargspec(arg)
    except TypeError:
        # On CPython 2.x, built-in methods of file aren't inspectable,
        # so if it's file.read() or file.write(), we can't tell it for sure.
        # Given how this check is being used, assuming the best is probably
        # all we can do here.
        return True
    else:
        if argnames and argnames[0] == 'self':
            argnames = argnames[1:]

    if min_arity is not None:
        actual_min_arity = len(argnames) - len(defaults or ())
        assert actual_min_arity >= 0, (
            "Minimum arity of %r found to be negative (got %s)!" % (
                arg, actual_min_arity))
        if int(min_arity) != actual_min_arity:
            return False

    if max_arity is not None:
        actual_max_arity = sys.maxsize if varargs or kwargs else len(argnames)
        if int(max_arity) != actual_max_arity:
            return False

    return True

def update(self, pbar):
        """
        Handle progress bar updates
        @type   pbar:   ProgressBar
        @rtype: str
        """
        if self.total is None:
            pbar.update(self.current)
        else:
            pbar.update(self.current, self.total)

def update(self, pbar):
        """
        Handle progress bar updates
        @type   pbar:   ProgressBar
        @rtype: str
        """
        if pbar.label != self._label:
            self.label = pbar.label

        return self.label

def get_visible_items(self):
        """Return a list of all visible items in the treewidget."""
        return [item for item in self.get_items() if item.isVisible()]

def get_visible_items(self):
        """Return a list of all visible items in the treewidget."""
        items = []
        iterator = QTreeWidgetItemIterator(self)
        while iterator.value():
            item = iterator.value()
            if not item.isHidden():
                if item.parent():
                    if item.parent().isExpanded():
                        items.append(item)
                else:
                    items.append(item)
            iterator += 1
        return items

def xhtml_escape(value: Union[str, bytes]) -> str:
    """Escapes a string so it is valid within HTML or XML.

    Escapes the characters ``<``, ``>``, ``"``, ``'``, and ``&``.
    When used in attribute values the escaped strings must be enclosed
    in quotes.

    .. versionchanged:: 3.2

       Added the single quote to the list of escaped characters.
    """
    if isinstance(value, str):
        return _xhtml_escape_impl(value)
    else:
        return _xhtml_escape_impl(value.decode("utf-8"))

def to_str(instance, encoding='utf-8'):
    """Convert an instance recursively to string."""
    if isinstance(instance, dict):
        return {k: to_str(v, encoding) for k, v in instance.items()}
    elif isinstance(instance, list):
        return [to_str(v, encoding) for v in instance]
    elif isinstance(instance, tuple):
        return tuple(to_str(v, encoding) for v in instance)
    elif isinstance(instance, str):
        return instance
    elif isinstance(instance, bytes):
        return instance.decode(encoding)
    else:
        return str(instance)

def to_str(instance, encoding='utf-8'):
    """Convert an instance recursively to string."""
    if isinstance(instance, str):
        return instance
    elif hasattr(instance, 'decode'):
        return instance.decode(encoding)
    elif isinstance(instance, list):
        return list([to_str(item, encoding) for item in instance])
    elif isinstance(instance, tuple):
        return tuple([to_str(item, encoding) for item in instance])
    elif isinstance(instance, dict):
        return dict(
            [(to_str(key, encoding), to_str(value, encoding))
                for key, value in instance.items()])
    else:
        return instance

def _from_pointer(pointer, incref):
        """Wrap an existing :c:type:`cairo_scaled_font_t *` cdata pointer.

        :type incref: bool
        :param incref:
            Whether increase the :ref:`reference count <refcounting>` now.
        :return: A new :class:`ScaledFont` instance.

        """
        if pointer is None:
            return None
        return ScaledFont(pointer, incref)

def body_block_supplementary_material_render(supp_tags, base_url=None):
    """fig and media tag caption may have supplementary material"""
    if not supp_tags:
        return ''
    if base_url is None:
        base_url = ''
    return '<div class="supplementary-material">' + \
        ''.join(
            '<div class="supplementary-material-{0}">{1}</div>'.format(
                tag['type'],
                '<a href="{0}{1}">{2}</a>'.format(
                    base_url,
                    tag['href'],
                    tag['caption']
                )
            ) for tag in supp_tags
        ) + \
        '</div>'

def body_block_supplementary_material_render(supp_tags, base_url=None):
    """fig and media tag caption may have supplementary material"""
    source_data = []
    for supp_tag in supp_tags:
        for block_content in body_block_content_render(supp_tag, base_url=base_url):
            if block_content != {}:
                if "content" in block_content:
                    del block_content["content"]
                source_data.append(block_content)
    return source_data

def find_video_file(rtdc_dataset):
        """Tries to find a video file that belongs to an RTDC dataset

        Returns None if no video file is found.
        """
        video_file = None
        for file in rtdc_dataset.files:
            if file.type == "video":
                video_file = file
                break
        return video_file

def _parse_tokenize(self, rule):
        """Tokenizer for the policy language."""
