        return rule.split()

def convert_ids_to_object_ids(obj_map):
    """converts string representations of _id back to ObjectId obj"""
    for key, value in obj_map.items():
        if key == "_id":
            obj_map[key] = ObjectId(value)
        elif isinstance(value, dict):
            obj_map[key] = convert_ids_to_object_ids(value)
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict):
                    obj_map[key] = convert_ids_to_object_ids(item)
    return obj_map

def convert_ids_to_object_ids(obj_map):
    """converts string representations of _id back to ObjectId obj"""
    converted_map = {}
    for key, value in obj_map.items():
        if key == '_id':
            # hacky, but using alias sends back the whole ID string, like
            #   assessment.Item%3A5758326b4a40452d6eee1fa1%40ODL.MIT.EDU
            # so we have to preserve it
            try:
                converted_map[key] = ObjectId(value)
            except InvalidId:
                converted_map[key] = value
        elif isinstance(value, dict):
            converted_map[key] = convert_ids_to_object_ids(value)
        elif isinstance(value, list):
            new_list = []
            for internal_item in value:
                if isinstance(internal_item, dict):
                    new_list.append(convert_ids_to_object_ids(internal_item))
                else:
                    new_list.append(internal_item)
            converted_map[key] = new_list
        else:
            converted_map[key] = value
    return converted_map

def get_components(self, other):
        """ Break this vector into one vector that is perpendicular to the 
        given vector and another that is parallel to it. """
        if other.is_zero():
            raise ValueError("Cannot get components of a vector with zero length")
        else:
            return self.project(other), self.reject(other)

def _connection(self):
        """
        If we have a pipeline, shared in thread, or in the good thread, return it
        else use the direct connection
        """
        if self.pipeline:
            return self.pipeline
        elif self.shared_connection:
            return self.shared_connection
        elif self.connection:
            return self.connection
        else:
            return self.direct_connection

