def _process_get_status(self, data):
        """ Processes a received STATUS message and notifies listeners. """
        if data.get('status') == 'OK':
            self._status = 'OK'
        elif data.get('status') == 'ERROR':
            self._status = 'ERROR'
        elif data.get('status') == 'WARNING':
            self._status = 'WARNING'
        elif data.get('status') == 'UNKNOWN':
            self._status = 'UNKNOWN'
        else:
            self._status = 'UNKNOWN'

        self._status_message = data.get('message')
        self._status_code = data.get('code')
        self._status_data = data.get('data')

        self._notify_status_listeners()

def validate_busy(func, *args, **kwargs):
    """
    A decorator that raises an exception if the specified target is busy.

    Expects the target ID to be either the 'target_id' param in kwargs,
    or the first positional parameter.

    Raises a TargetBusyException if the target does not exist.
    """
    target_id = kwargs.get('target_id', args[0])
    if target_id is None:
        raise ValueError('target_id must be specified')

    target = Target.get(target_id)
    if target is None:
        raise TargetBusyException('Target %s does not exist' % target_id)

    if target.busy:
        raise TargetBusyException('Target %s is busy' % target_id)

    return func(*args, **kwargs)

def validate_busy(func, *args, **kwargs):
    """
    A decorator that raises an exception if the specified target is busy.

    Expects the target ID to be either the 'target_id' param in kwargs,
    or the first positional parameter.

    Raises a TargetBusyException if the target does not exist.
    """
    def inner(self, *args, **kwargs):
        # find the target param
        target_id = None
        if 'target_id' in kwargs and kwargs['target_id'] != None:
            target_id = kwargs['target_id']
        else:
            target_id = 0

        # if there was a target specified, ensure it's not busy
        if self.target_is_busy(target_id):
            raise TargetBusyException()

        # call the function
        return func(self, *args, **kwargs)
    return inner

def when_closed(self):
        """
        Returns a Deferred that callback()'s (with this Circuit instance)
        when this circuit hits CLOSED or FAILED.
        """
        if self.state in ['CLOSED', 'FAILED']:
            return defer.succeed(self)
        return self._when_closed.when_fired()

def add_done_callback(self, fn):
        """Attach the provided callable to the future.

        The provided function is called, with this future as its only argument,
        when the future finishes running.
        """
        if self.done():
            return fn(self)
        self._callbacks.append(fn)

