def getfunc(obj, name=''):
    """Get the function corresponding to name from obj, not the method."""
    return getattr(obj, name)

def getfunc(obj, name=''):
    """Get the function corresponding to name from obj, not the method."""
    if name:
        obj = getattr(obj, name)
    return getattr(obj, '__func__', obj)

def push(self, my_dict, key, element):
        """ Push an element onto an array that may not have been defined in
        the dict """
        if key not in my_dict:
            my_dict[key] = []
        my_dict[key].append(element)

def push(self, my_dict, key, element):
        """ Push an element onto an array that may not have been defined in
        the dict """
        group_info = my_dict.setdefault(key, [])
        if isinstance(group_info, dict):
            host_list = group_info.setdefault('hosts', [])
            host_list.append(element)
        else:
            group_info.append(element)

def parse_block(self, block_id, txs):
        """
        Given the sequence of transactions in a block, turn them into a
        sequence of virtual chain operations.

        Return the list of successfully-parsed virtualchain transactions
        """
        vc_txs = []
        for tx in txs:
            try:
                vc_txs.append(self.parse_tx(tx))
            except Exception as e:
                self.logger.error("Failed to parse tx %s: %s", tx, e)
        return vc_txs

def clear_lock(self, lock_type='update'):
        """
        Clear update.lk
        """
        if lock_type == 'update':
            self.update_lock = False
        elif lock_type == 'insert':
            self.insert_lock = False
        elif lock_type == 'delete':
            self.delete_lock = False
        elif lock_type == 'select':
            self.select_lock = False
        else:
            raise Exception("Invalid lock type")

def _set_instance_ip(self):
        """
        Get the IP address based on instance ID.

        If public IP address not found attempt to get private IP.
        """
        try:
            self.instance_ip = self.ec2_client.describe_instances(
                InstanceIds=[self.instance_id]
            )["Reservations"][0]["Instances"][0]["PublicIpAddress"]
        except IndexError:
            self.instance_ip = self.ec2_client.describe_instances(
                InstanceIds=[self.instance_id]
            )["Reservations"][0]["Instances"][0]["PrivateIpAddress"]

def _set_instance_ip(self):
        """
        Get the IP address based on instance ID.

        If public IP address not found attempt to get private IP.
        """
        try:
            ip_address = self.network.public_ip_addresses.get(
                self.running_instance_id, self.public_ip_name
            ).ip_address
        except Exception:
            try:
                ip_address = self.network.network_interfaces.get(
                    self.running_instance_id, self.nic_name
                ).ip_configurations[0].private_ip_address
            except Exception as error:
                raise AzureCloudException(
                    'Unable to retrieve instance IP address: {0}.'.format(
                        error
                    )
                )

        self.instance_ip = ip_address

def write_to_file(self, destination_path):
        """
        Writes the metadata json or xml to a file.

        :param destination_path: the file path the file format is inferred
        from the destination_path extension.
        :type destination_path: str
        :return: the written metadata
        :rtype: str
        """
        if destination_path.endswith('.json'):
            return self.write_to_json(destination_path)
        elif destination_path.endswith('.xml'):
            return self.write_to_xml(destination_path)
        else:
            raise ValueError('Unknown file extension for metadata file.')

def _post_build(self, module, encoding):
        """Handles encoding and delayed nodes after a module has been built"""
        module.file_encoding = encoding
        self._manager.cache_module(module)
        # post tree building steps after we stored the module in the cache:
        for from_node in module._import_from_nodes:
            if from_node.modname == "__future__":
                for symbol, _ in from_node.names:
                    module.future_imports.add(symbol)
            self.add_from_names_to_locals(from_node)
        # handle delayed assattr nodes
        for delayed in module._delayed_assattr:
            self.delayed_assattr(delayed)

        # Visit the transforms
        if self._apply_transforms:
            module = self._manager.visit_transforms(module)
        return module

