        :param      editor  | <QtGui.QWidget>
                    model   | <QtGui.QModel>
                    index   | <QtGui.QModelIndex>
        """
        if index.isValid():
            if model.data(index, Qt.EditRole) != editor.text():
                model.setData(index, editor.text(), Qt.EditRole)

