def get_eol(self):
        """Read the next token and raise an exception if it isn't EOL or
        EOF.

        @raises dns.exception.SyntaxError:
        @rtype: string
        """
        token = self.get_token()
        if token != 'EOL':
            raise dns.exception.SyntaxError(
                'Expected EOL, got %r' % token)
        return token

def get_eol(self):
        """Read the next token and raise an exception if it isn't EOL or
        EOF.

        @raises dns.exception.SyntaxError:
        @rtype: string
        """

        token = self.get()
        if not token.is_eol_or_eof():
            raise dns.exception.SyntaxError('expected EOL or EOF, got %d "%s"' % (token.ttype, token.value))
        return token.value

def _product_filter(products) -> str:
    """Calculate the product filter."""
    return " ".join(
        [
            f"{product.name} {product.description} {product.price} {product.category}"
            for product in products
        ]
    )

def _product_filter(products) -> str:
    """Calculate the product filter."""
    _filter = 0
    for product in {PRODUCTS[p] for p in products}:
        _filter += product
    return format(_filter, "b")[::-1]

def get_type(full_path):
    """Get the type (socket, file, dir, symlink, ...) for the provided path"""
    if os.path.isdir(full_path):
        return 'dir'
    elif os.path.isfile(full_path):
        return 'file'
    elif os.path.islink(full_path):
        return 'symlink'
    elif os.path.ismount(full_path):
        return 'mount'
    elif os.path.issocket(full_path):
        return 'socket'
    elif os.path.isblockdev(full_path):
        return 'blockdev'
    elif os.path.isfifo(full_path):
        return 'fifo'
    else:
        return 'unknown'

def get_type(full_path):
    """Get the type (socket, file, dir, symlink, ...) for the provided path"""
    status = {'type': []}
    if os.path.ismount(full_path):
        status['type'] += ['mount-point']
    elif os.path.islink(full_path):
        status['type'] += ['symlink']
    if os.path.isfile(full_path):
        status['type'] += ['file']
    elif os.path.isdir(full_path):
        status['type'] += ['dir']
    if not status['type']:
        if os.stat.S_ISSOCK(status['mode']):
            status['type'] += ['socket']
        elif os.stat.S_ISCHR(status['mode']):
            status['type'] += ['special']
        elif os.stat.S_ISBLK(status['mode']):
            status['type'] += ['block-device']
        elif os.stat.S_ISFIFO(status['mode']):
            status['type'] += ['pipe']
    if not status['type']:
        status['type'] += ['unknown']
    elif status['type'] and status['type'][-1] == 'symlink':
        status['type'] += ['broken']
    return status['type']

def _locate_schemas(self, schemas, skip_missing_schemas):
        """Locate all schemas (look in openldap store).

        If skip_missing_schemas is True, ignore missing schemas;
        otherwise, raise.
        """
        for schema in schemas:
            if not self.schema_exists(schema):
                if skip_missing_schemas:
                    continue
                raise ldaperrors.NoSuchObject(
                    'Schema %s does not exist' % schema)

def _locate_schemas(self, schemas, skip_missing_schemas):
        """Locate all schemas (look in openldap store).

        If skip_missing_schemas is True, ignore missing schemas;
        otherwise, raise.
        """
        for schema in schemas:
            if schema == os.path.abspath(schema):
                schema_file = schema
            else:
                schema_file = os.path.join(self.paths.schemas, schema)

            if os.path.isfile(schema_file):
                # Absolute path: use it.
                yield schema_file
            elif skip_missing_schemas:
                logger.warning("Unable to locate schema %s at %s", schema, schema_file)
            else:
                raise PathError("Unable to locate schema %s at %s" % (schema, schema_file))

def merge_deployment_data(dict1: DeployedContracts, dict2: DeployedContracts) -> DeployedContracts:
    """ Take contents of two deployment JSON files and merge them

    The dictionary under 'contracts' key will be merged. The 'contracts'
    contents from different JSON files must not overlap. The contents
    under other keys must be identical.
    """
    if not isinstance(dict1, dict) or not isinstance(dict2, dict):
        raise TypeError("merge_deployment_data expects two dictionaries")

    if 'contracts' not in dict1 or 'contracts' not in dict2:
        raise ValueError("merge_deployment_data expects two dictionaries with 'contracts' key")

    if not isinstance(dict1['contracts'], dict) or not isinstance(dict2['contracts'], dict):
        raise TypeError("merge_deployment_data expects two dictionaries with 'contracts' key")

    if set(dict1['contracts'].keys()) != set(dict2['contracts'].keys()):
        raise ValueError("merge_deployment_data expects two dictionaries with identical 'contracts' keys")

    dict1['contracts'].update(dict2['contracts'])
    return dict1

def _validated(self, value):
        """Format the value or raise a :exc:`ValidationError` if an error occurs."""
        try:
            return self.validate(value)
        except ValidationError as e:
            raise ValidationError(
                self.error_messages['invalid'],
                code='invalid',
                params={'value': value},
            ) from e

def _validated(self, value):
        """Format the value or raise a :exc:`ValidationError` if an error occurs."""
        if value is None:
            return None
        if isinstance(value, bson.ObjectId):
            return value
        try:
            return bson.ObjectId(value)
        except (ValueError, AttributeError):
            self.fail('invalid_object_id')

