def _normalize_sort_SQL(self, field_name, field_vals, sort_dir_str):
        """
        allow sorting by a set of values

        http://stackoverflow.com/questions/3303851/sqlite-and-custom-order-by
        """
        if sort_dir_str == 'asc':
            sort_dir = 'ASC'
        elif sort_dir_str == 'desc':
            sort_dir = 'DESC'
        else:
            raise Exception('Invalid sort direction: %s' % sort_dir_str)

        if field_name == 'id':
            field_name = 'id'
        elif field_name == 'name':
            field_name = 'name'
        elif field_name == 'description':
            field_name = 'description'
        elif field_name == 'created_at':
            field_name = 'created_at'
        elif field_name == 'updated_at':
            field_name = 'updated_at'
        elif field_name == 'deleted_at':
            field_name = 'deleted_at'
        elif field_name == 'created_by':
            field_name = 'created_by'
        elif field_name == 'updated_by':
            field_name = 'updated_by'
        elif field_name == 'deleted_by':
            field_name = 'deleted_by'
        else:
            raise Exception('Invalid field name: %s' % field_name)

        if field_name == 'id':
            field_vals = [int(x) for x in field_vals]
            field_vals = ','.join([str(x) for x in field_vals])
            return 'id IN (%s)' % field_vals, sort_dir
        elif field_name == 'name':
            field_vals = [x.replace("'", "''") for x in field_vals]
            field_vals = ','.join([str(x) for x in field_vals])
            return 'name IN (%s)' % field_vals, sort_dir
        elif field_name == 'description':
            field_vals = [x.replace("'", "''") for x in field_vals]
            field_vals = ','.join([str(x) for x in field_vals])
            return 'description IN (%s)' % field_vals, sort

