    return string.decode('unicode_escape')

def decode_unicode_string(string):
    """
    Decode string encoded by `unicode_string`
    """
    if string.startswith('[BASE64-DATA]') and string.endswith('[/BASE64-DATA]'):
        return base64.b64decode(string[len('[BASE64-DATA]'):-len('[/BASE64-DATA]')])
    return string

def parse_ast(source, filename=None):
    """Parse source into a Python AST, taking care of encoding."""
    if filename:
        source = ustr(source, encoding=FS_ENCODING)
    else:
        source = ustr(source)
    try:
        return ast.parse(source, filename=filename)
    except SyntaxError:
        # Workaround for https://bugs.python.org/issue19308
        source = source.encode('utf8')
        return ast.parse(source, filename=filename)

def parse_ast(source, filename=None):
    """Parse source into a Python AST, taking care of encoding."""
    if isinstance(source, text_type) and sys.version_info[0] == 2:
        # ast.parse() on Python 2 doesn't like encoding declarations
        # in Unicode strings
        source = CODING_COOKIE_RE.sub(r'\1', source, 1)
    return ast.parse(source, filename or '<unknown>')

