def _process_cascaded_category_contents(records):
    """
    Travel from categories to subcontributions, flattening the whole event structure.

    Yields everything that it finds (except for elements whose protection has changed
    but are not inheriting their protection settings from anywhere).

    :param records: queue records to process
    """
    while records:
        record = records.popleft()
        if record.is_category:
            # If this is a category, we need to process its subcontributions
            for subrecord in record.subcontributions:
                subrecord.parent = record
                records.append(subrecord)
        else:
            # If this is a subcontribution, we need to process its elements
            for element in record.elements:
                element.parent = record
                records.append(element)
            # If this is a subcontribution, we need to process its categories
            for category in record.categories:
                category.parent = record
                records.append(category)

def from_dict(data, ctx):
        """
        Instantiate a new TradeOpen from a dict (generally from loading a JSON
        response). The data used to instantiate the TradeOpen is a shallow copy
        of the dict passed in, with any complex child types instantiated
        appropriately.
        """
        data = data.copy()
        if 'id' in data:
            data['id'] = int(data['id'])
        if 'price' in data:
            data['price'] = float(data['price'])
        if 'quantity' in data:
            data['quantity'] = float(data['quantity'])
        if 'side' in data:
            data['side'] = data['side'].lower()
        if 'time' in data:
            data['time'] = ctx.iso8601_to_utc_datetime(data['time'])
        if 'type' in data:
            data['type'] = data['type'].lower()
        return TradeOpen(**data)

def from_dict(data, ctx):
        """
        Instantiate a new TradeOpen from a dict (generally from loading a JSON
        response). The data used to instantiate the TradeOpen is a shallow copy
        of the dict passed in, with any complex child types instantiated
        appropriately.
        """

        data = data.copy()

        if data.get('units') is not None:
            data['units'] = ctx.convert_decimal_number(
                data.get('units')
            )

        if data.get('price') is not None:
            data['price'] = ctx.convert_decimal_number(
                data.get('price')
            )

        if data.get('guaranteedExecutionFee') is not None:
            data['guaranteedExecutionFee'] = ctx.convert_decimal_number(
                data.get('guaranteedExecutionFee')
            )

        if data.get('clientExtensions') is not None:
            data['clientExtensions'] = \
                ctx.transaction.ClientExtensions.from_dict(
                    data['clientExtensions'], ctx
                )

        if data.get('halfSpreadCost') is not None:
            data['halfSpreadCost'] = ctx.convert_decimal_number(
                data.get('halfSpreadCost')
            )

        if data.get('initialMarginRequired') is not None:
            data['initialMarginRequired'] = ctx.convert_decimal_number(
                data.get('initialMarginRequired')
            )

        return TradeOpen(**data)

def components(self, obj, fmt=None, comm=True, **kwargs):
        """
        Returns data and metadata dictionaries containing HTML and JS
        components to include render in app, notebook, or standalone
        document. Depending on the backend the fmt defines the format
        embedded in the HTML, e.g. png or svg. If comm is enabled the
        JS code will set up a Websocket comm channel using the
        currently defined CommManager.
        """
        if fmt is None:
            fmt = self.fmt
        if fmt not in self.components:
            self.components[fmt] = {}
        if comm is True:
            comm = self.comm
        if comm is not False:
            self.components[fmt]['comm'] = comm
        self.components[fmt]['data'] = self.get_data(obj, **kwargs)
        self.components[fmt]['metadata'] = self.get_metadata(obj, **kwargs)
        return self.components[fmt]

