        if self.sigma_d is None:
            raise ValueError("No sigma_d defined")
        if self.sigma_m is None:
            raise ValueError("No sigma_m defined")
        if self.sigma_f is None:
            raise ValueError("No sigma_f defined")
        if self.sigma_n is None:
            raise ValueError("No sigma_n defined")
        if self.sigma_d is None:
            raise ValueError("No sigma_d defined")
        if self.sigma_m is None:
            raise ValueError("No sigma_m defined")
        if self.sigma_f is None:
            raise ValueError("No sigma_f defined")
        if self.sigma_n is None:
            raise ValueError("No sigma_n defined")
        if self.sigma_d is None:
            raise ValueError("No sigma_d defined")
        if self.sigma_m is None:
            raise ValueError("No sigma_m defined")

def predict_y(self, xq, sigma=None, k=None, **kwargs):
        """Provide an prediction of xq in the output space

        @param xq  an array of float of length dim_x
        """
        sigma = sigma or self.sigma
        k = k or self.k
        dists, index = self.dataset.nn_x(xq, k = k)
        w = self._weights(dists, sigma*sigma)
        return np.sum([wi*self.dataset.get_y(idx) for wi, idx in zip(w, index)], axis = 0)

def get_version(path=VERSION_PATH):
    """
    Reads the python file defined in the VERSION_PATH to find the get_version
    function, and executes it to ensure that it is loaded correctly. Separating
    the version in this way ensures no additional code is executed.
    """
    namespace = {}
    exec(read(path), namespace)
    return namespace['get_version'](short=True)

