def to_internal_value(self, data):
        """
        Validate that the input is a decimal number and return a Decimal
        instance.
        """
        if data is None:
            return None
        if isinstance(data, Decimal):
            return data
        if isinstance(data, (int, float)):
            return Decimal(str(data))
        if isinstance(data, six.string_types):
            return Decimal(data)
        raise ValidationError(self.error_messages['invalid'])

def to_internal_value(self, data):
        """
        Validate that the input is a decimal number and return a Decimal
        instance.
        """
        data = smart_text(data).strip()
        if len(data) > self.MAX_STRING_LENGTH:
            self.fail('max_string_length')

        try:
            value = decimal.Decimal(data)
        except decimal.DecimalException:
            self.fail('invalid')

        # Check for NaN. It is the only value that isn't equal to itself,
        # so we can use this to identify NaN values.
        if value != value:
            self.fail('invalid')

        # Check for infinity and negative infinity.
        if value in (decimal.Decimal('Inf'), decimal.Decimal('-Inf')):
            self.fail('invalid')

        return self.validate_precision(value)

def cleanup_images(self):
        """
        Remove all images created by CONU and remove all hidden images (cached dowloads)

        :return: None
        """
        images = self.client.images.list()
        for image in images:
            if image.tags:
                for tag in image.tags:
                    if tag.startswith("conu"):
                        self.client.images.remove(image.id, force=True)
                        break

        # remove hidden images
        images = self.client.images.list(all=True)
        for image in images:
            if image.attrs["Parent"] == "":
                self.client.images.remove(image.id, force=True)

def cleanup_images(self):
        """
        Remove all images created by CONU and remove all hidden images (cached dowloads)

        :return: None
        """
        for image in self.list_images():
            if CONU_ARTIFACT_TAG in image.name:
                image.rmi()
        # remove all hidden images -> causes trouble when pulling the image again
        run_cmd(["machinectl", "--no-pager", "clean"])

