def assign_variable_names(self):
        """
        Assign default names to all variables.

        :return: None
        """
        for variable in self.variables:
            if variable.name is None:
                variable.name = 'var' + str(variable.id)

def assign_variable_names(self):
        """
        Assign default names to all variables.

        :return: None
        """

        for var in self._variables:
            if isinstance(var, SimStackVariable):
                if var.name is not None:
                    continue
                if var.ident.startswith('iarg'):
                    var.name = 'arg_%x' % var.offset
                else:
                    var.name = 's_%x' % (-var.offset)
                    # var.name = var.ident
            elif isinstance(var, SimRegisterVariable):
                if var.name is not None:
                    continue
                var.name = var.ident

def audio_stream_capture(self, httptype=None,
                             channel=None, path_file=None):
        """
        Params:

            path_file - path to output file
            channel: - integer
            httptype - type string (singlepart or multipart)

                singlepart: HTTP content is a continuos flow of audio packets
                multipart: HTTP content type is multipart/x-mixed-replace, and
                           each audio packet ends with a boundary string

        """
        if not path_file:
            raise ValueError("path_file is required")

        if not channel:
            raise ValueError("channel is required")

        if not httptype:
            raise ValueError("httptype is required")

        if httptype == "singlepart":
            self.stream_capture_singlepart(path_file, channel)
        elif httptype == "multipart":
            self.stream_capture_multipart(path_file, channel)
        else:
            raise ValueError("httptype must be singlepart or multipart")

def build_image_from_inherited_image(self, image_name: str, image_tag: str,
                                         repo_path: Path,
                                         requirements_option: RequirementsOptions):
        """
        Builds a image with installed requirements from the inherited image. (Or just tags the image
        if there are no requirements.)

        See :meth:`build_image` for parameters descriptions.

        :rtype: docker.models.images.Image
        """
        if requirements_option is None:
            return self.tag_image(image_name, image_tag, repo_path)
        else:
            return self.build_image(image_name, image_tag, repo_path, requirements_option)

def ASCII_encoding(self):
        """Returns the ASCII encoding of a string"""
        return self.encode('ascii')

def get(self, idx, default=''):
        """Returns the element at idx, or default if idx is beyond the length of the list"""
        return self.data[idx] if idx < len(self.data) else default

def get(self, idx, default=''):
        """Returns the element at idx, or default if idx is beyond the length of the list"""
        # if the index is beyond the length of the list, return ''
        if isinstance(idx, int) and (idx >= len(self) or idx < -1 * len(self)):
            return default
        # else do the regular list function (for int, slice types, etc.)
        return super().__getitem__(idx)

def setDaemon(self, runnable, isdaemon, noregister = False):
        """
        If a runnable is a daemon, it will not keep the main loop running. The main loop will end when all alived runnables are daemons.
        """
        if not isinstance(runnable, Runnable):
            raise TypeError("runnable must be a Runnable")
        if noregister:
            self.daemons.append(runnable)
        else:
            self.daemons.append(runnable)
            self.register(runnable)
        runnable.setDaemon(isdaemon)

def setDaemon(self, runnable, isdaemon, noregister = False):
        """
        If a runnable is a daemon, it will not keep the main loop running. The main loop will end when all alived runnables are daemons.
        """
        if not noregister and runnable not in self.registerIndex:
            self.register((), runnable)
        if isdaemon:
            self.daemons.add(runnable)
        else:
            self.daemons.discard(runnable)

def from_dict(cls, val):
        """Creates dict2 object from dict object

        Args:
            val (:obj:`dict`): Value to create from

        Returns:
            Equivalent dict2 object.
        """
        if isinstance(val, dict2):
            return val

        elif isinstance(val, dict):
            res = cls()
            for k, v in val.items():
                res[k] = cls.from_dict(v)
            return res

        elif isinstance(val, list):
            res = []
            for item in val:
                res.append(cls.from_dict(item))
            return res
        else:
            return val

def supported_currencies(self, project='moneywagon', level="full"):
        """
        Returns a list of all currencies that are supported by the passed in project.
        and support level. Support level can be: "block", "transaction", "address"
        or "full".
        """
        ret = []
        if project == 'multiexplorer-wallet':
            for currency, data in self.sorted_crypto_data:
                if not data.get("bip44_coin_type"):
                    continue
                if len(data.get('services', {}).get("push_tx", [])) < 1:
                    continue
                if len(data.get('services', {}).get("historical_transactions", [])) < 1:
                    continue
                if len(data.get('services', {}).get("single_transaction", [])) < 1:
                    continue
                if len(data.get('services', {}).get("unspent_outputs", [])) < 1:
                    continue
                ret.append(currency)

            altcore_tx = self.supported_currencies('altcore', level="transaction")
            return [x for x in ret if x in altcore_tx]

        for symbol, data in self.sorted_crypto_data:
            if symbol == '': # template
                continue
            if self.is_all_supported(data, project, level):
                ret.append(symbol)
        return ret

def _read_line(self, f):
        """
        Reads one non empty line (if it's a comment, it skips it).
        """
        while True:
            line = f.readline()
            if not line:
                return None
            if line[0] == '#':
                continue
            return line.strip()

