        """Parses the global config and returns the hostname value

        Returns:
            dict: The configured value for hostname.  The returned dict
                object is intended to be merged into the resource dict
        """
        hostname = self.config.get('hostname')
        if hostname:
            return {'hostname': hostname}
        return {}

def install(self, destination):
        """ Install a third party odoo add-on

        :param string destination: the folder where the add-on should end up at.
        """
        if not os.path.exists(destination):
            os.makedirs(destination)
        if not os.path.isdir(destination):
            raise OdooError("destination is not a directory")
        if not os.access(destination, os.W_OK):
            raise OdooError("destination is not writable")
        if not os.access(destination, os.X_OK):
            raise OdooError("destination is not executable")
        if not self.url:
            raise OdooError("url is required")
        if not self.name:
            raise OdooError("name is required")
        if not self.version:
            raise OdooError("version is required")
        if not self.description:
            raise OdooError("description is required")
        if not self.author:
            raise OdooError("author is required")
        if not self.license:
            raise OdooError("license is required")
        if not self.website:
            raise OdooError("website is required")
        if not self.category:
            raise OdooError("category is required")
        if not self.depends:
            raise OdooError("depends is required")
        if not self.data:
            raise OdooError("data is required")
        if not self.demo:
            raise OdooError("demo is required")
        if not self.installable:
            raise OdooError("installable is required")
        if not self.auto_install:
            raise OdooError("auto_install is required")
        if not self.qweb:
            raise OdooError("qweb is required")
        if not self.demo_xml:
            raise OdooError("demo_xml is required")
        if not self.demo_json:
            raise OdooError("demo_json is required")
        if not self.demo_images:
            raise OdooError("demo_images is required")
        if not self.demo_data:
            raise OdooError("demo_data is required")
        if not self.post_load:
            raise Odoo

