def accounts(dbpath, output, format, account,
             config=None, tag=None, tagprefix=None, region=(),
             not_region=(), not_bucket=None):
    """Report on stats by account"""
    db = get_db(dbpath)
    if not db:
        return
    if not account:
        print("Error: must specify --account")
        return
    if not format:
        print("Error: must specify --format")
        return
    if not output:
        print("Error: must specify --output")
        return
    if config:
        config = get_config(config)
    else:
        config = {}
    if tag:
        if not tagprefix:
            print("Error: must specify --tagprefix")
            return
        tag = tagprefix + tag
    if not region:
        region = get_region(config)
    if not not_region:
        not_region = get_not_region(config)
    if not_bucket:
        not_bucket = get_not_bucket(config)
    if not config:
        config = {}
    if not config.get('accounts'):
        print("Error: must specify --accounts in config")
        return
    if not config.get('buckets'):
        print("Error: must specify --buckets in config")
        return
    if not config.get('regions'):
        print("Error: must specify --regions in config")
        return
    if not config.get('not_regions'):
        print("Error: must specify --not_regions in config")
        return
    if not config.get('not_buckets'):
        print("Error: must specify --not_buckets in config")
        return
    if not config.get('account_tag'):
        print("Error: must specify --account_tag in config")
        return
    if not config.get('bucket_tag'):
        print("Error: must specify --bucket_tag in config")
        return
    if not config.get('region_tag'):
        print("Error: must specify --region_tag in config")
        return
    if not config.get('not_region_tag'):
        print("Error: must specify --not_region_tag in config")
        return
    if not config.get('not_bucket_tag'):
        print("Error: must specify --not_bucket_tag in config")

def accounts(dbpath, output, format, account,
             config=None, tag=None, tagprefix=None, region=(),
             not_region=(), not_bucket=None):
    """Report on stats by account"""
    d = db.db(dbpath)
    accounts = d.accounts()
    formatter = (
        format == 'csv' and format_accounts_csv or format_accounts_plain)

    if region:
        for a in accounts:
            a.buckets = [b for b in a.buckets if b.region in region]
        accounts = [a for a in accounts if a.bucket_count]

    if not_region:
        for a in accounts:
            a.buckets = [b for b in a.buckets if b.region not in not_region]
        accounts = [a for a in accounts if a.bucket_count]

    if not_bucket:
        for a in accounts:
            a.buckets = [b for b in a.buckets if b.name not in not_bucket]
    if config and tagprefix:
        account_map = {account.name: account for account in accounts}

        with open(config) as fh:
            account_data = json.load(fh).get('accounts')
        tag_groups = {}
        for a in account_data:
            if tag is not None and tag not in a['tags']:
                continue

            for t in a['tags']:
                if t.startswith(tagprefix):
                    tvalue = t[len(tagprefix):]
                    if not tvalue:
                        continue
                    if tvalue not in tag_groups:
                        tag_groups[tvalue] = db.Account(tvalue, [])
                    account_results = account_map.get(a['name'])
                    if not account_results:
                        print("missing %s" % a['name'])
                        continue
                    tag_groups[tvalue].buckets.extend(
                        account_map[a['name']].buckets)
        accounts = tag_groups.values()

    formatter(accounts, output)

